// utils/atomic-json.ts. A complete JSON body is written to an exclusive sibling
// temporary file before rename publishes it. Cleanup and the caller receipt follow.
module AtomicJsonPublication {
  pure val Writers = Set(1, 2)
  type Writer = { stage: str, temporary: str, renamed: bool, result: str, receipt: str }
  type State = { file: int, serial: bool, writers: int -> Writer }
  pure val queued: Writer = {
    stage: "queued", temporary: "absent", renamed: false,
    result: "pending", receipt: "pending",
  }
  pure def initial(serial: bool): State = {
    file: 0, serial: serial, writers: Writers.mapBy(_ => queued),
  }
  var s: State

  action init = s' = initial(false)
  action serialInit = s' = initial(true)

  // Same-process async calls are admitted in invocation order. Distinct
  // processes, or a synchronous call beside an async one, have no shared tail.
  action admit(writer: int, created: bool): bool = {
    val own = s.writers.get(writer)
    all {
      own.stage == "queued",
      not(s.serial) or writer == 1 or s.writers.get(1).stage == "settled",
      s' = s.with("writers", s.writers.set(writer, {
        ...own, stage: if (created) "writing" else "cleanup",
        temporary: if (created) "partial" else "absent",
        result: if (created) "pending" else "failure",
      })),
    }
  }

  action finishWrite(writer: int, success: bool): bool = {
    val own = s.writers.get(writer)
    all {
      own.stage == "writing",
      s' = s.with("writers", s.writers.set(writer, {
        ...own, stage: if (success) "renaming" else "cleanup",
        temporary: if (success) "complete" else "partial",
        result: if (success) "pending" else "failure",
      })),
    }
  }

  action rename(writer: int, success: bool): bool = {
    val own = s.writers.get(writer)
    all {
      own.stage == "renaming", own.temporary == "complete",
      s' = { ...s, file: if (success) writer else s.file,
        writers: s.writers.set(writer, {
          ...own, stage: "cleanup", renamed: success,
          temporary: if (success) "absent" else "complete",
          result: if (success) "success" else "failure",
        }),
      },
    }
  }

  // A failed rm is diagnostic and cannot replace the publication outcome.
  action cleanup(writer: int, removed: bool): bool = {
    val own = s.writers.get(writer)
    all {
      own.stage == "cleanup",
      s' = s.with("writers", s.writers.set(writer, {
        ...own, stage: "settled", receipt: own.result,
        temporary: if (removed) "absent" else own.temporary,
      })),
    }
  }

  // Process death skips finally. A published rename can outlive an absent
  // caller receipt, and a pre-rename temporary file can remain on disk.
  action crash(writer: int): bool = {
    val own = s.writers.get(writer)
    all {
      not(s.serial), Set("writing", "renaming", "cleanup").contains(own.stage),
      s' = s.with("writers", s.writers.set(writer,
        { ...own, stage: "crashed", receipt: "unknown" })),
    }
  }

  action advance(writer: int): bool = {
    nondet success = Set(false, true).oneOf()
    any { admit(writer, success), finishWrite(writer, success),
      rename(writer, success), cleanup(writer, success) }
  }
  action step = any { advance(1), advance(2), crash(1), crash(2), s' = s }

  val ReadersSeePublishedSnapshot = s.file == 0 or s.writers.get(s.file).renamed
  val ReceiptRequiresRename = Writers.forall(writer => {
    val own = s.writers.get(writer)
    (own.receipt == "success" implies own.renamed) and
      (own.receipt == "failure" implies not(own.renamed)) and
      (own.receipt == "unknown" implies own.stage == "crashed")
  })
  val QueueRetainsOrder = s.serial and s.writers.get(1).stage != "settled"
    implies s.writers.get(2) == queued

  temporal PublishedDataSurvivesCleanup = always(and {
    s.file != next(s.file) implies Writers.exists(writer =>
      s.writers.get(writer).stage == "renaming" and next(s.file) == writer
        and next(s.writers.get(writer).renamed)),
    Writers.forall(writer =>
      s.writers.get(writer).renamed implies next(s.writers.get(writer).renamed)),
    Writers.forall(writer =>
      s.writers.get(writer).stage == "crashed" implies
        next(s.writers.get(writer)) == s.writers.get(writer)),
  }.orKeep(s))
  temporal WritesSettle = eventually(Writers.forall(writer =>
    Set("settled", "crashed").contains(s.writers.get(writer).stage)))
  temporal FairWritesSettle =
    (advance(1).weakFair(s) and advance(2).weakFair(s)) implies WritesSettle

  run OrderedAsyncCallsTest = serialInit.then(admit(1, true)).then(finishWrite(1, true))
    .expect(s.file == 0 and s.writers.get(2) == queued)
    .then(rename(1, true)).then(cleanup(1, true)).then(admit(2, true))
    .then(finishWrite(2, true)).then(rename(2, true)).then(cleanup(2, true))
    .expect(s.file == 2 and ReceiptRequiresRename)
  run FailedRenameDoesNotPoisonNextCallTest = serialInit.then(admit(1, true))
    .then(finishWrite(1, true)).then(rename(1, false)).then(cleanup(1, true))
    .expect(s.file == 0 and s.writers.get(1).receipt == "failure")
    .then(admit(2, true)).then(finishWrite(2, true)).then(rename(2, true)).then(cleanup(2, true))
    .expect(s.file == 2 and s.writers.get(2).receipt == "success")
  run IndependentWritersPublishWholeSnapshotsTest = init.then(admit(1, true)).then(admit(2, true))
    .then(finishWrite(2, true)).then(rename(2, true)).then(finishWrite(1, true))
    .then(rename(1, true)).then(cleanup(2, true)).then(cleanup(1, true))
    .expect(s.file == 1 and ReadersSeePublishedSnapshot and ReceiptRequiresRename)
  run PreRenameDeathLeavesOwnTemporaryFileTest = init.then(admit(1, true))
    .then(finishWrite(1, true)).then(crash(1))
    .expect(s.file == 0 and s.writers.get(1).temporary == "complete")
    .then(admit(2, true)).then(finishWrite(2, true)).then(rename(2, true)).then(cleanup(2, true))
    .expect(s.file == 2 and s.writers.get(1).temporary == "complete")
  run PostRenameDeathLeavesUnknownCallerReceiptTest = init.then(admit(1, true))
    .then(finishWrite(1, true)).then(rename(1, true)).then(crash(1))
    .expect(s.file == 1 and s.writers.get(1).receipt == "unknown" and ReceiptRequiresRename)
  run CleanupFailurePreservesWriteFailureTest = init.then(admit(1, true))
    .then(finishWrite(1, false)).then(cleanup(1, false))
    .expect(s.file == 0 and s.writers.get(1).receipt == "failure"
      and s.writers.get(1).temporary == "partial")
}

// One service generation, its replacement, and the actual per-room queue.
// Topic labels are symbolic and distinct; this projection stays below capacity.
module ChannelTopicRetirement {
  pure val Rooms = Set(0, 1)
  pure val Calls = Set(0, 1, 2, 3)
  pure val OldCalls = Set(0, 1, 2)
  pure def room(id: int): int = if (id == 2) 1 else 0
  type Call = { phase: str, readOnly: bool }
  type Topics = { queue: List[int], hydrated: bool, local: List[int], durable: List[int] }
  var s: { owner: str, rooms: int -> Topics, calls: int -> Call, stopOwned: Set[int] }

  action init = s' = {
    owner: "original", stopOwned: Set(),
    rooms: Rooms.mapBy(_ => { queue: List(), hydrated: false, local: List(), durable: List() }),
    calls: Calls.mapBy(_ => { phase: "idle", readOnly: false })
  }
  def entry(id: int): Call = s.calls.get(id)
  def topics(id: int): Topics = s.rooms.get(room(id))
  def inProgress(id: int): bool = entry(id).phase.in(Set("hydrating", "ready", "writing"))
  def accepted(id: int): bool = not(entry(id).phase.in(Set("idle", "refused")))
  def pending(id: int): bool = entry(id).phase == "queued" or inProgress(id)
  def permitted(id: int): bool =
    if (OldCalls.contains(id)) s.owner == "original" else s.owner == "replacement"
  action update(id: int, call: Call, updated: Topics): bool = s' = { ...s,
    calls: s.calls.set(id, call), rooms: s.rooms.set(room(id), updated)
  }

  action invoke(id: int, readOnly: bool): bool = all {
    entry(id).phase == "idle",
    // Only original call 0 can be a cold read. Call 3 is invoked after reload.
    not(readOnly) or id == 0,
    id != 3 or s.owner == "replacement",
    if (permitted(id)) update(id, { phase: "queued", readOnly: readOnly },
      { ...topics(id), queue: topics(id).queue.append(id) })
    else update(id, { phase: "refused", readOnly: readOnly }, topics(id))
  }
  action start(id: int): bool = all {
    entry(id).phase == "queued", topics(id).queue.length() > 0,
    topics(id).queue.head() == id,
    update(id, { ...entry(id), phase: if (topics(id).hydrated) "ready" else "hydrating" }, topics(id))
  }
  action hydrate(id: int, ok: bool): bool = all {
    entry(id).phase == "hydrating",
    if (ok) update(id, { ...entry(id), phase: "ready" },
      { ...topics(id), hydrated: true, local: topics(id).durable })
    else update(id, { ...entry(id), phase: "failed" },
      { ...topics(id), queue: topics(id).queue.tail() })
  }
  action apply(id: int): bool = all {
    entry(id).phase == "ready",
    if (entry(id).readOnly) update(id, { ...entry(id), phase: "done" },
      { ...topics(id), queue: topics(id).queue.tail() })
    else update(id, { ...entry(id), phase: "writing" },
      { ...topics(id), local: topics(id).local.append(id) })
  }
  action persist(id: int, ok: bool): bool = all {
    entry(id).phase == "writing",
    update(id, { ...entry(id), phase: if (ok) "done" else "failed" }, {
      ...topics(id), queue: topics(id).queue.tail(),
      durable: if (ok) topics(id).local else topics(id).durable
    })
  }
  action beginStop = all {
    s.owner == "original",
    s' = { ...s, owner: "stopping", stopOwned: OldCalls.filter(accepted) }
  }
  action finishStop = all {
    s.owner == "stopping", OldCalls.forall(id => not(pending(id))),
    s' = { ...s, owner: "retired", rooms: Rooms.mapBy(r =>
      { ...s.rooms.get(r), hydrated: false, local: List() }) }
  }
  action replace = all {
    s.owner == "retired", s' = { ...s, owner: "replacement" }
  }
  action advance(id: int): bool = any {
    start(id), apply(id), { nondet ok = Bool.oneOf(); any { hydrate(id, ok), persist(id, ok) } }
  }
  action step = any {
    { nondet id = Calls.oneOf(); nondet readOnly = Bool.oneOf(); invoke(id, readOnly) },
    { nondet id = Calls.oneOf(); advance(id) },
    beginStop, finishStop, replace, s' = s
  }

  val RoomOrder = Rooms.forall(r => {
    val q = s.rooms.get(r).queue
    Calls.filter(id => room(id) == r and inProgress(id)).forall(id =>
      q.length() > 0 and q.head() == id)
  })
  val NoLateOriginalAdmission = s.owner != "original" implies OldCalls.filter(accepted) == s.stopOwned
  val RetirementJoinsOriginal = s.owner.in(Set("retired", "replacement")) implies
    OldCalls.forall(id => not(pending(id)))
  val RetirementClearsLocal = s.owner == "retired" implies Rooms.forall(r =>
    not(s.rooms.get(r).hydrated) and s.rooms.get(r).local == List())
  val RoomIsolation = Rooms.forall(r => {
    val row = s.rooms.get(r)
    row.local.indices().forall(i => room(row.local.nth(i)) == r) and
      row.durable.indices().forall(i => room(row.durable.nth(i)) == r)
  })
  temporal StopSettles = (s.owner == "stopping").leadsTo(s.owner.in(Set("retired", "replacement")))
  temporal FairStopSettles = (finishStop.weakFair(s) and Calls.forall(id => advance(id).weakFair(s)))
    .implies(StopSettles)
  temporal FairAcceptedCallsSettle = Calls.forall(id => advance(id).weakFair(s)).implies(
    Calls.forall(id => pending(id).leadsTo(not(pending(id)))))

  run replacementHydratesAndRetiredRefusesTest = init.then(invoke(0, false)).then(start(0))
    .then(hydrate(0, true)).then(apply(0)).then(beginStop).then(invoke(1, false))
    .expect(NoLateOriginalAdmission and entry(1).phase == "refused")
    .then(persist(0, true)).then(finishStop).then(replace).then(invoke(2, false))
    .then(invoke(3, false)).then(start(3)).then(hydrate(3, true)).then(apply(3))
    .then(persist(3, true)).expect(s.rooms.get(0).durable == List(0, 3)
      and entry(2).phase == "refused" and RetirementJoinsOriginal)
  run failedWriteStillReleasesOrderedRoomTest = init.then(invoke(0, false)).then(invoke(1, false))
    .then(start(0)).then(hydrate(0, true)).then(apply(0)).then(persist(0, false))
    .expect(s.rooms.get(0).durable == List() and entry(0).phase == "failed")
    .then(start(1)).then(apply(1)).then(persist(1, true))
    .expect(s.rooms.get(0).durable == List(0, 1))
  run coldReadOrdersSameRoomWhileOtherRoomAdvancesTest = init.then(invoke(0, true))
    .then(invoke(1, false)).then(invoke(2, false)).then(start(0)).then(start(2))
    .then(hydrate(2, true)).then(apply(2)).then(persist(2, true)).then(hydrate(0, true))
    .then(apply(0)).then(start(1)).then(apply(1)).then(persist(1, true))
    .expect(RoomOrder and RoomIsolation and s.rooms.get(0).durable == List(1)
      and s.rooms.get(1).durable == List(2))
}

{
	"sources": [
		"packages/core/src/utils/confirmation.ts",
		"packages/core/test/confirmation-reply-model.test.ts",
		"packages/core/test/confirmation.test.ts",
		"packages/core/quint/check-confirmation-reply.mjs"
	],
	"conformance": "packages/core/quint/check-confirmation-reply.mjs",
	"bounds": "One destructive-action prompt in one of the seven languages whose yes and no words the classifier lists: English, Spanish, French, German and Korean, which put a space between words, and Chinese and Japanese, which do not. Each reply has one to three words drawn from the language's yes word, its word for \"not\" and an ordinary word; a comma follows the first word, and in Chinese and Japanese the other words run together with no space. The conformance script replays every generated reply sequence through requireConfirmation on an initialized runtime and requires all 273 one-reply cases (39 per language). Questions, thanks, politeness fillers, emoji, other no words (never, cancel, wait) and other languages are covered by test/confirmation.test.ts, not by this model. Under weak fairness of a settling reply the prompt is eventually confirmed or cancelled. Explicit stuttering lets the user stay silent or keep answering unclearly, so the same claim without fairness must fail. No reply-time bound is proved.",
	"cases": [
		{
			"name": "first-replies-in-seven-languages",
			"main": "ConfirmationReply",
			"init": "init",
			"step": "step",
			"invariants": [
				"NoWordCancels",
				"NoWordNeverConfirms",
				"PlainYesConfirms",
				"UnclearReplyAsksAgain",
				"TypeOK"
			],
			"temporal": ["ReplySettles", "ReplySettlesWithoutFairness"],
			"maxSteps": 3,
			"samples": 12000,
			"temporalChecks": [
				{
					"property": "ReplySettles",
					"expect": "holds",
					"assumptions": [
						"Every continuously enabled settling reply (one with a no word or one that opens with a yes) eventually arrives (weak fairness). This checks that such a reply confirms or cancels the prompt, not how long the user takes to answer."
					]
				},
				{
					"property": "ReplySettlesWithoutFairness",
					"expect": "counterexample",
					"assumptions": [
						"No reply fairness is assumed. The user may stay silent or keep answering unclearly forever, so a temporal loop counterexample is required."
					]
				}
			]
		}
	]
}

// requireConfirmation (packages/core/src/utils/confirmation.ts) holds a
// destructive action until the user answers its prompt. A reply with a no
// word anywhere cancels it. A reply that opens with a yes and has no no word
// confirms it. Any other reply leaves it pending, and the prompt is asked
// again.
// language: 0 English, 1 Spanish, 2 French, 3 German, 4 Korean, which put a
// space between words; 5 Chinese and 6 Japanese, which do not.
// A reply is a list of one to three words: 0 the language's yes word
// (yes, sí, oui, ja, 확인, 确认, はい), 1 its no word for "not" (not, no,
// pas, nicht, 아니요, 不要, いいえ), 2 an ordinary word (now). A comma
// follows the first word; in Chinese and Japanese the other words run
// together with no space ("确认，现在不要").
// status: 0 pending, 1 confirmed, 2 cancelled.
module ConfirmationReply {
  pure val Languages = 0.to(6)
  pure val Words = 0.to(2)
  var language: int
  var reply: List[int]
  var status: int

  pure def has(list: List[int], value: int): bool =
    list.indices().exists(i => list[i] == value)
  pure def words(count: int, first: int, second: int, third: int): List[int] =
    [first, second, third].slice(0, count)
  pure def decide(r: List[int]): int =
    if (has(r, 1)) 2
    else if (r[0] == 0) 1
    else 0
  // A reply that settles the prompt: it has a no word or opens with a yes.
  pure def clear(r: List[int]): bool = has(r, 1) or r[0] == 0

  action init = {
    nondet chosen = Languages.oneOf()
    all { language' = chosen, reply' = [], status' = 0 }
  }
  action answer(settles: bool): bool = {
    nondet count = 1.to(3).oneOf()
    nondet first = Words.oneOf()
    nondet second = Words.oneOf()
    nondet third = Words.oneOf()
    val r = words(count, first, second, third)
    all {
      status == 0,
      clear(r) == settles,
      language' = language, reply' = r, status' = decide(r)
    }
  }
  // The user may not answer, or may keep answering unclearly.
  action stutter = all {
    language' = language, reply' = reply, status' = status
  }
  action step = any { answer(true), answer(false), stutter }

  val ModelState = { language: language, reply: reply, status: status }
  temporal ReplySettlesWithoutFairness = (status == 0).leadsTo(status != 0)
  temporal ReplySettles = answer(true).weakFair(ModelState)
    .implies(ReplySettlesWithoutFairness)

  val NoWordCancels = reply.length() == 0 or not(has(reply, 1)) or status == 2
  val NoWordNeverConfirms = status != 1 or not(has(reply, 1))
  val PlainYesConfirms =
    reply.length() == 0 or has(reply, 1) or reply[0] != 0 or status == 1
  val UnclearReplyAsksAgain =
    reply.length() == 0 or clear(reply) or status == 0
  val TypeOK =
    Languages.contains(language) and Set(0, 1, 2).contains(status) and
    reply.length() <= 3 and reply.indices().forall(i => Words.contains(reply[i])) and
    (reply.length() == 0 implies status == 0)
}

