// Recovery owns one background load per runtime. Its cooldown advances with
// elapsed time. Wall-clock adjustments do not affect admission.
module NotificationRecovery {
  type RequestReceipt = { outcome: str, busy: bool, cooling: bool, availability: str }
  type State = {
    availability: str,
    phase: str,
    failures: int,
    remaining: int,
    receipt: RequestReceipt
  }
  var s: State

  pure val availabilities = Set("failed", "pending", "registering", "registered", "disabled")
  // Six represents every failure count at or above the first capped delay.
  pure val delays = List(0, 1, 2, 4, 8, 16, 30)
  pure def delay(failures: int): int = delays.nth(failures)

  action init = s' = {
    availability: "failed", phase: "idle", failures: 0, remaining: 0,
    receipt: { outcome: "none", busy: false, cooling: false, availability: "failed" }
  }

  action request = {
    // A successful load releases the recovery map before its finally runs.
    val busy = Set("loading", "failure-finally").contains(s.phase)
    val eligible = not(busy) and s.availability == "failed" and s.remaining == 0
    val registered = not(busy) and s.availability == "registered"
    s' = { ...s,
      receipt: { busy: busy, cooling: s.remaining > 0, availability: s.availability,
        outcome: if (busy) "in-flight"
          else if (s.availability != "failed") "unavailable"
          else if (s.remaining > 0) "backoff" else "started" },
      phase: if (eligible) "loading" else s.phase,
      availability: if (eligible) "registering" else s.availability,
      failures: if (registered) 0 else s.failures,
      remaining: if (registered) 0 else s.remaining }
  }

  action loaded = all {
    s.phase == "loading",
    s' = { ...s, phase: "success-finally", availability: "registered",
      failures: 0, remaining: 0 },
  }
  action failed = all {
    s.phase == "loading",
    val failures = if (s.failures == 6) 6 else s.failures + 1
    s' = { ...s, phase: "failure-finally", availability: "failed",
      failures: failures, remaining: delay(failures) },
  }
  action finalize = all {
    Set("success-finally", "failure-finally").contains(s.phase),
    s' = { ...s, phase: "idle" },
  }
  action tick = all {
    s.remaining > 0,
    s' = { ...s, remaining: s.remaining - 1 },
  }
  action cooldownElapsed = all {
    s.remaining > 0,
    s' = { ...s, remaining: 0 },
  }
  action externalAvailability(availability: str): bool = all {
    s.phase == "idle",
    s' = { ...s, availability: availability },
  }
  // A wall-clock jump or an idle observer has no effect on elapsed time.
  action wallClockAdjusted = s' = s
  action step = {
    nondet availability = availabilities.oneOf()
    any {
      request, loaded, failed, finalize, tick, cooldownElapsed,
      externalAvailability(availability), wallClockAdjusted
    }
  }

  val BusyRequestsJoin = s.receipt.busy.implies(s.receipt.outcome == "in-flight")
  val BackoffBlocksAdmission = (s.receipt.outcome == "started").implies(not(s.receipt.cooling))
  val OnlyFailedServicesStart = (s.receipt.outcome == "started").implies(s.receipt.availability == "failed")
  val BoundedCooldown = all {
    s.failures >= 0 and s.failures <= 6,
    s.remaining >= 0 and s.remaining <= delay(s.failures),
  }
  val PhaseMatchesAvailability = all {
    (s.phase == "loading").implies(s.availability == "registering"),
    (s.phase == "success-finally").implies(s.availability == "registered"),
    (s.phase == "failure-finally").implies(s.availability == "failed"),
  }
  temporal OnlyIdleEntersLoad = always((
    (s.phase != "loading" and next(s.phase) == "loading").implies(s.phase == "idle")
  ).orKeep(s))
  temporal AttemptsSettle = (loaded.weakFair(s) and failed.weakFair(s)
    and finalize.weakFair(s)).implies((s.phase != "idle").leadsTo(s.phase == "idle"))
  temporal CooldownElapses = (s.remaining > 0).leadsTo(s.remaining == 0)
  temporal FairCooldownElapses = tick.weakFair(s).implies(CooldownElapses)

  run pendingCatchStillJoinsTest = init.then(request).then(failed).then(request)
    .expect(s.receipt.outcome == "in-flight" and s.phase == "failure-finally")
    .then(finalize).then(request).expect(s.receipt.outcome == "backoff" and s.phase == "idle")
  run retryRestoresReadinessTest = init.then(request).then(failed).then(finalize).then(tick)
    .then(request).then(loaded).then(request).expect(s.receipt.outcome == "unavailable")
    .then(finalize).expect(s.availability == "registered" and s.failures == 0)
  run disabledServiceIsUnavailableTest = init.then(externalAvailability("disabled"))
    .then(request).expect(s.receipt.outcome == "unavailable" and s.phase == "idle")
  run wallAdjustmentLeavesCooldownTest = init.then(request).then(failed).then(finalize)
    .then(wallClockAdjusted).then(request).expect(s.receipt.outcome == "backoff" and s.remaining == 1)
    .then(tick).then(request).expect(s.receipt.outcome == "started")
  run capSaturatesTest = init
    .then(request).then(failed).then(finalize).then(cooldownElapsed)
    .then(request).then(failed).then(finalize).then(cooldownElapsed)
    .then(request).then(failed).then(finalize).then(cooldownElapsed)
    .then(request).then(failed).then(finalize).then(cooldownElapsed)
    .then(request).then(failed).then(finalize).then(cooldownElapsed)
    .then(request).then(failed).expect(s.remaining == 30)
    .then(finalize).then(cooldownElapsed).then(request).then(failed)
    .expect(s.failures == 6 and s.remaining == 30)
}

// One runtime can replace its mapped recovery while an older load receipt is
// still being delivered. Each callback retains its own coordinator record.
module NotificationRecoveryOwnership {
  type Recovery = { phase: str, cooling: bool }
  val Owners = Set(1, 2)
  val availabilities = Set("failed", "pending", "registering", "registered", "disabled")
  val busyPhases = Set("loading", "returned", "failure-finally")
  var s: { availability: str, mapped: int, allocated: int, records: int -> Recovery,
    receipt: { outcome: str, busy: bool, cooling: bool, availability: str } }
  val mappedBusy = if (s.mapped == 0) false else busyPhases.contains(s.records.get(s.mapped).phase)
  val mappedCooling = if (s.mapped == 0) false else s.records.get(s.mapped).cooling

  action init = s' = { availability: "failed", mapped: 0, allocated: 0,
    records: Owners.mapBy(_ => { phase: "idle", cooling: false }),
    receipt: { outcome: "none", busy: false, cooling: false, availability: "failed" } }
  action request = {
    val eligible = not(mappedBusy) and s.availability == "failed" and not(mappedCooling)
    val owner = if (s.mapped != 0) s.mapped else if (s.allocated == 0) 1 else 2
    all {
      not(eligible) or s.mapped != 0 or s.allocated < 2,
      s' = { ...s, receipt: { busy: mappedBusy, cooling: mappedCooling, availability: s.availability,
          outcome: if (mappedBusy) "in-flight" else if (s.availability != "failed") "unavailable"
            else if (mappedCooling) "backoff" else "started" },
        mapped: if (eligible) owner else if (not(mappedBusy) and s.availability == "registered") 0 else s.mapped,
        allocated: if (eligible and s.mapped == 0) s.allocated + 1 else s.allocated,
        records: if (eligible) s.records.set(owner, { phase: "loading", cooling: false }) else s.records,
        availability: if (eligible) "registering" else s.availability },
    }
  }
  action externalAvailability(availability: str): bool = s' = { ...s, availability: availability }
  action observeRegistered = all {
    s.availability == "registered", s' = { ...s, mapped: 0 },
  }
  action returnLoad(owner: int): bool = all {
    s.records.get(owner).phase == "loading", s.availability == "registered",
    s' = { ...s, records: s.records.set(owner, { ...s.records.get(owner), phase: "returned" }) },
  }
  action succeed(owner: int): bool = all {
    s.records.get(owner).phase == "returned",
    s' = { ...s, mapped: if (s.mapped == owner) 0 else s.mapped,
      records: s.records.set(owner, { ...s.records.get(owner), phase: "success-finally" }) },
  }
  action loadFailed(owner: int): bool = all {
    s.records.get(owner).phase == "loading",
    s' = { ...s, records: s.records.set(owner, { phase: "failure-finally", cooling: true }) },
  }
  action finalize(owner: int): bool = all {
    Set("success-finally", "failure-finally").contains(s.records.get(owner).phase),
    s' = { ...s, records: s.records.set(owner, { ...s.records.get(owner), phase: "idle" }) },
  }
  action cooldownElapsed(owner: int): bool = all {
    s.records.get(owner).cooling,
    s' = { ...s, records: s.records.set(owner, { ...s.records.get(owner), cooling: false }) },
  }
  // The logger, runtime error boundary and event bus catch their observers.
  action diagnosticObserverThrows = s' = s
  action complete(owner: int): bool = any {
    returnLoad(owner), succeed(owner), loadFailed(owner), finalize(owner),
  }
  action step = {
    nondet owner = Owners.oneOf()
    nondet availability = availabilities.oneOf()
    any { request, externalAvailability(availability), observeRegistered, complete(owner),
      cooldownElapsed(owner), diagnosticObserverThrows }
  }

  val BusyRequestsJoin = s.receipt.busy.implies(s.receipt.outcome == "in-flight")
  val CoolingCurrentEntryBacksOff = (not(s.receipt.busy) and s.receipt.cooling
    and s.receipt.availability == "failed").implies(s.receipt.outcome == "backoff")
  val SuccessfulReceiptReleasesItsOwnMap = (s.mapped != 0)
    .implies(s.records.get(s.mapped).phase != "success-finally")
  temporal StaleSuccessPreservesCurrentOwner = always(Owners.forall(owner =>
    (s.records.get(owner).phase == "returned" and next(s.records.get(owner).phase) == "success-finally"
      and s.mapped != owner).implies(next(s.mapped) == s.mapped)).orKeep(s))
  temporal StaleFailurePreservesCurrentOwner = always(Owners.forall(owner =>
    (s.records.get(owner).phase == "loading" and next(s.records.get(owner).phase) == "failure-finally"
      and s.mapped != owner).implies(next(s.mapped) == s.mapped)).orKeep(s))
  temporal DetachedFinallyPreservesCurrentOwner = always(Owners.forall(owner =>
    (Set("success-finally", "failure-finally").contains(s.records.get(owner).phase)
      and next(s.records.get(owner).phase) == "idle" and s.mapped != owner)
        .implies(next(s.mapped) == s.mapped)).orKeep(s))
  temporal AttemptsSettle = Owners.forall(owner => complete(owner).weakFair(s))
    .implies(Owners.forall(owner => (s.records.get(owner).phase != "idle")
      .leadsTo(s.records.get(owner).phase == "idle")))

  run lateSuccessRetainsReplacementBackoffTest = init.then(request)
    .then(externalAvailability("registered")).then(returnLoad(1)).then(observeRegistered)
    .then(externalAvailability("failed")).then(request).then(succeed(1))
    .expect(s.mapped == 2).then(externalAvailability("failed"))
    .then(loadFailed(2)).then(diagnosticObserverThrows).then(finalize(2))
    .then(finalize(1)).then(request).expect(s.receipt.outcome == "backoff")
  run diagnosticFailureDoesNotClearCooldownTest = init.then(request)
    .then(externalAvailability("failed")).then(loadFailed(1))
    .then(diagnosticObserverThrows).then(finalize(1)).then(request)
    .expect(s.receipt.outcome == "backoff" and s.mapped == 1)
}

// Single-runtime admission queue, durable approval boundaries and reply retention.
// SQL operations can fail. Removing expired rows is separate from eligibility.
module PairingAdmission {
  pure val senders = Set(0, 1, 2)
  pure val none = -1
  var s: { rows: int -> str, active: int, phase: str, result: str,
    observedCount: int, lastSender: int, created: bool }
  action init = s' = { rows: senders.mapBy(_ => "absent"), active: none,
    phase: "idle", result: "idle", observedCount: 0, lastSender: 0, created: false }
  action enter(sender: int): bool = all {
    s.phase == "idle",
    s' = { ...s, active: sender, phase: "reading", result: "pending", created: false },
  }
  action read = all {
    s.phase == "reading",
    val count = senders.filter(sender => s.rows.get(sender) == "live").size()
    s' = { ...s, observedCount: count,
      phase: if (s.rows.get(s.active) == "live") "updating"
        else if (count >= 2) "rejecting" else "creating" },
  }
  action write(ok: bool): bool = all {
    Set("updating", "creating").contains(s.phase),
    s' = { ...s, rows: if (ok and s.phase == "creating") s.rows.set(s.active, "live") else s.rows,
      lastSender: s.active, active: none, phase: "idle", result: if (ok) "ok" else "failed",
      created: ok and s.phase == "creating" },
  }
  action reject = all {
    s.phase == "rejecting",
    s' = { ...s, lastSender: s.active, active: none, phase: "idle", result: "full", created: false },
  }
  action expire(sender: int): bool = all {
    s.rows.get(sender) == "live",
    s' = { ...s, rows: s.rows.set(sender, "expired") },
  }
  action clean(sender: int): bool = all {
    s.rows.get(sender) == "expired",
    s' = { ...s, rows: s.rows.set(sender, "absent") },
  }
  action step = {
    nondet sender = senders.oneOf()
    any { enter(sender), read, write(true), write(false), reject, expire(sender), clean(sender), s' = s }
  }
  val PendingLimit = senders.filter(sender => s.rows.get(sender) == "live").size() <= 2
  val SingleAdmission = (s.phase == "idle") == (s.active == none)
  val AdmissionUsesBoundedRead = (s.phase == "creating").implies(s.observedCount < 2)
  // The model separates expiry after read from update. Updating a previously
  // eligible row does not renew createdAt and therefore does not revive it.
  temporal QueueProgress = (step.weakFair(s) and read.weakFair(s)
    and write(true).weakFair(s) and reject.weakFair(s)).implies(
      (s.phase != "idle").leadsTo(s.phase == "idle"))
  run capRejectsNewSenderTest = init.then(enter(0)).then(read).then(write(true))
    .then(enter(1)).then(read).then(write(true)).then(enter(2)).then(read).then(reject)
    .expect(s.result == "full" and PendingLimit)
  run failedWriteDoesNotPoisonQueueTest = init.then(enter(0)).then(read).then(write(false))
    .then(enter(1)).then(read).then(write(true)).expect(s.result == "ok" and s.rows.get(0) == "absent")
  run expiryDuringUpdateDoesNotRenewTest = init.then(enter(0)).then(read).then(write(true))
    .then(enter(0)).then(read).then(expire(0)).then(write(true)).expect(s.rows.get(0) == "expired")
}

module PairingApprovalRecovery {
  var s: { request: bool, grant: bool, phase: str, result: str, consumedWithoutGrant: bool }
  action init = s' = { request: true, grant: false, phase: "idle", result: "none", consumedWithoutGrant: false }
  action begin = all {
    s.phase == "idle" and s.request,
    s' = { ...s, phase: "grant", result: "pending" },
  }
  action grant(ok: bool): bool = all {
    s.phase == "grant",
    s' = { ...s, grant: s.grant or ok, phase: if (ok) "consume" else "idle",
      result: if (ok) "pending" else "failed" },
  }
  action consume(ok: bool): bool = all {
    s.phase == "consume",
    s' = { ...s, request: s.request and not(ok), phase: "idle", result: if (ok) "ok" else "failed",
      consumedWithoutGrant: s.consumedWithoutGrant or (ok and not(s.grant)) },
  }
  action step = any { begin, grant(true), grant(false), consume(true), consume(false), s' = s }
  val GrantPrecedesConsumption = not(s.consumedWithoutGrant)
  val SuccessfulApprovalHasGrant = (s.result == "ok").implies(s.grant and not(s.request))
  val FailedWriteRetainsCode = (not(s.grant)).implies(s.request)
  temporal SuccessfulRetryProgress = (begin.weakFair(s) and grant(true).strongFair(s)
    and consume(true).strongFair(s)).implies((s.request).leadsTo(not(s.request)))
  run grantFailureCanRetryTest = init.then(begin).then(grant(false)).then(begin)
    .then(grant(true)).then(consume(true)).expect(SuccessfulApprovalHasGrant)
  run failedConsumptionRetainsGrantTest = init.then(begin).then(grant(true)).then(consume(false))
    .then(begin).then(grant(true)).then(consume(true)).expect(SuccessfulApprovalHasGrant)
}

module PairingReplyWindow {
  pure val senders = Set(0, 1, 2)
  var s: { retained: List[int], live: Set[int], lastSender: int, accepted: bool, wasRetained: bool }
  action init = s' = { retained: [], live: Set(), lastSender: 0, accepted: false, wasRetained: false }
  action claim(sender: int): bool = {
    val held = s.retained.indices().exists(i => s.retained.nth(i) == sender) and s.live.contains(sender)
    val fresh = if (s.retained.length() >= 2)
      s.retained.select(owner => s.live.contains(owner)) else s.retained
    val bounded = if (fresh.length() >= 2) fresh.tail() else fresh
    val updated = if (bounded.indices().exists(i => bounded.nth(i) == sender)) bounded else bounded.append(sender)
    s' = if (held) { ...s, lastSender: sender, accepted: false, wasRetained: true }
      else { retained: updated, live: s.live.union(Set(sender)), lastSender: sender,
        accepted: true, wasRetained: false }
  }
  action expire(sender: int): bool = s' = { ...s, live: s.live.exclude(Set(sender)) }
  action step = { nondet sender = senders.oneOf(); any { claim(sender), expire(sender) } }
  val CacheBound = s.retained.length() <= 2
  val RetainedLiveClaimSuppressesReply = s.wasRetained.implies(not(s.accepted))
  val UniqueRetainedKeys = s.retained.foldl(Set(), (result, sender) => result.union(Set(sender))).size() == s.retained.length()
  run expiryRearmsReplyTest = init.then(claim(0)).then(claim(0)).expect(not(s.accepted))
    .then(expire(0)).then(claim(0)).expect(s.accepted)
  run evictionRearmsReplyTest = init.then(claim(0)).then(claim(1)).then(claim(2))
    .then(claim(0)).expect(s.accepted and CacheBound)
}

// Identity projection of PairingService and SQL pairing writes. Owner values
// stand for (agent, channel, sender) tuples. Fresh request UUIDs and collision-
// resistant hashing of canonical grant tuples are assumed; raw bits are omitted.
module PairingIdentityOwners {
  pure val owners = Set(0, 1, 2, 3, 4)
  // 0/1 differ at a hyphen-delimited channel/sender boundary. 0/2 differ only
  // in agent. 3/4 differ at a colon-delimited reply-claim boundary.
  pure def legacyRequestKey(owner: int): int = if (owner <= 2) 0 else owner
  pure def legacyReplyKey(owner: int): int = if (owner == 4) 3 else owner
}

module PairingReplyIdentity {
  import PairingIdentityOwners.*
  var s: { ownersSeen: Set[int], claimKeys: Set[int], accepted: bool, first: bool }
  action init = s' = { ownersSeen: Set(), claimKeys: Set(), accepted: true, first: true }
  action claim(owner: int, legacy: bool): bool = {
    val key = if (legacy) legacyReplyKey(owner) else owner
    s' = {
      ownersSeen: s.ownersSeen.union(Set(owner)),
      claimKeys: s.claimKeys.union(Set(key)),
      accepted: not(s.claimKeys.contains(key)),
      first: not(s.ownersSeen.contains(owner)),
    }
  }
  action step = { nondet owner = owners.oneOf(); claim(owner, false) }
  val IndependentClaimScopes = s.first.implies(s.accepted)
  val ClaimOncePerOwner = s.accepted.implies(s.first)
  run distinctScopesReceiveRepliesTest = init.then(claim(3, false)).then(claim(4, false))
    .expect(IndependentClaimScopes and s.accepted)
  run oldDelimitedKeyAliasesScopesTest = init.then(claim(3, true)).then(claim(4, true))
    .expect(not(IndependentClaimScopes))
}

module PairingRequestIdentity {
  import PairingIdentityOwners.*
  var s: { rows: int -> int, accepted: bool }
  action init = s' = { rows: owners.mapBy(_ => -1), accepted: true }
  action admit(owner: int, legacy: bool): bool = {
    val key = if (legacy) legacyRequestKey(owner) else owner
    val accepted = s.rows.get(key) == -1 or s.rows.get(key) == owner
    s' = { rows: if (accepted) s.rows.set(key, owner) else s.rows, accepted: accepted }
  }
  action step = { nondet owner = owners.oneOf(); admit(owner, false) }
  val IndependentRequestScopes = s.accepted
  val RowsRetainTheirScope = owners.forall(owner => s.rows.get(owner) == -1 or s.rows.get(owner) == owner)
  run distinctTupleRequestsRemainIndependentTest = init.then(admit(0, false)).then(admit(1, false))
    .then(admit(2, false)).expect(IndependentRequestScopes)
  run oldTimestampIdentityAliasesAgentsTest = init.then(admit(0, true)).then(admit(2, true))
    .expect(not(IndependentRequestScopes))
}

module PairingGrantIdentity {
  pure val owners = Set(0, 1, 2)
  pure val rowKeys = Set(0, 1, 2)
  var s: { rows: int -> int, ownerKey: int -> int,
    lastOwner: int, lastKey: int, accepted: bool, reported: bool }
  action init = s' = { rows: rowKeys.mapBy(_ => -1), ownerKey: owners.mapBy(_ => -1),
    lastOwner: 0, lastKey: 0, accepted: false, reported: false }
  action write(owner: int, key: int): bool = {
    val stored = s.ownerKey.get(owner)
    val insert = stored == -1 and s.rows.get(key) == -1
    val accepted = stored >= 0 or insert
    s' = {
      rows: if (insert) s.rows.set(key, owner) else s.rows,
      ownerKey: if (insert) s.ownerKey.set(owner, key) else s.ownerKey,
      lastOwner: owner, lastKey: if (stored >= 0) stored else key,
      accepted: accepted, reported: true,
    }
  }
  // Models the former unconditional ID return after ON CONFLICT DO NOTHING.
  action legacyWrite(owner: int, key: int): bool = {
    val insert = s.ownerKey.get(owner) == -1 and s.rows.get(key) == -1
    s' = {
      rows: if (insert) s.rows.set(key, owner) else s.rows,
      ownerKey: if (insert) s.ownerKey.set(owner, key) else s.ownerKey,
      lastOwner: owner, lastKey: key, accepted: true, reported: true,
    }
  }
  action remove(key: int): bool = {
    val owner = s.rows.get(key)
    s' = { ...s, rows: s.rows.set(key, -1),
      ownerKey: if (owner >= 0) s.ownerKey.set(owner, -1) else s.ownerKey,
      reported: false }
  }
  action step = {
    nondet owner = owners.oneOf()
    nondet key = rowKeys.oneOf()
    any { write(owner, key), remove(key) }
  }
  val ReceiptMatchesStoredScope = not(s.reported) or not(s.accepted) or s.rows.get(s.lastKey) == s.lastOwner
  val GrantIndexesAgree = owners.forall(owner => s.ownerKey.get(owner) == -1 or
    s.rows.get(s.ownerKey.get(owner)) == owner) and rowKeys.forall(key => s.rows.get(key) == -1 or
    s.ownerKey.get(s.rows.get(key)) == key)
  run existingGrantReturnsActualIdentityTest = init.then(write(0, 0)).then(write(0, 1))
    .expect(s.lastKey == 0 and ReceiptMatchesStoredScope)
  run conflictingScopeCannotReportSuccessTest = init.then(write(0, 0)).then(write(1, 0))
    .expect(not(s.accepted) and ReceiptMatchesStoredScope)
  run oldConflictReturnFabricatesReceiptTest = init.then(legacyWrite(0, 0)).then(legacyWrite(1, 0))
    .expect(not(ReceiptMatchesStoredScope))
  run oldDuplicateReturnFabricatesIdentityTest = init.then(legacyWrite(0, 0)).then(legacyWrite(0, 1))
    .expect(not(ReceiptMatchesStoredScope))
}

// One exact content/ruleset key and two requests. Admission and processing
// check the same marker, but simultaneous misses do not claim the key.
module PiiScrubSettlement {
  pure val Requests = Set(0, 1)
  pure val MaxAttempts = 4
  type Request = { phase: str, attempts: int, committedAt: int, notice: str }
  var s: { marker: bool, requests: int -> Request }

  action init = s' = {
    marker: false,
    requests: Requests.mapBy(_ => {
      phase: "idle", attempts: 0, committedAt: 0, notice: "none"
    })
  }
  def entry(id: int): Request = s.requests.get(id)
  action update(id: int, request: Request): bool =
    s' = { ...s, requests: s.requests.set(id, request) }

  action submit(id: int): bool = all {
    entry(id).phase == "idle",
    update(id, { ...entry(id), phase: if (s.marker) "deduplicated" else "queued" })
  }
  action beginAttempt(id: int): bool = all {
    entry(id).phase == "queued", entry(id).attempts < MaxAttempts,
    update(id, { ...entry(id), attempts: entry(id).attempts + 1,
      phase: if (s.marker) "deduplicated" else "scrubbing"
    })
  }
  action failAttempt(id: int): bool =
    update(id, { ...entry(id),
      phase: if (entry(id).attempts == MaxAttempts) "failing" else "queued"
    })
  action settleScrub(id: int, ok: bool): bool = all {
    entry(id).phase == "scrubbing",
    if (ok) update(id, { ...entry(id), phase: "marking" }) else failAttempt(id)
  }
  action settleMarker(id: int, confirmed: bool): bool = all {
    entry(id).phase == "marking",
    if (confirmed) s' = { marker: true,
      requests: s.requests.set(id, { ...entry(id),
        phase: "notifying", committedAt: entry(id).attempts
      })
    } else failAttempt(id)
  }
  action settleNotice(id: int, ok: bool): bool = all {
    entry(id).phase == "notifying",
    update(id, { ...entry(id), phase: "done", notice: if (ok) "sent" else "rejected" })
  }
  action settleFailureNotice(id: int): bool = all {
    entry(id).phase == "failing",
    update(id, { ...entry(id), phase: "exhausted" })
  }
  action advance(id: int): bool = any {
    beginAttempt(id), settleFailureNotice(id),
    { nondet ok = Bool.oneOf(); any {
      settleScrub(id, ok), settleMarker(id, ok), settleNotice(id, ok)
    } }
  }
  action step = any {
    { nondet id = Requests.oneOf(); any { submit(id), advance(id) } },
    s' = s
  }

  val CompletionRequiresReceipt = Requests.forall(id =>
    (entry(id).phase == "notifying" or entry(id).notice != "none") implies
      (s.marker and entry(id).committedAt > 0))
  val ConfirmedAttemptCannotRetry = Requests.forall(id =>
    (entry(id).committedAt > 0) implies all {
      entry(id).attempts == entry(id).committedAt,
      entry(id).phase.in(Set("notifying", "done"))
    })
  val NoPrematureExhaustion = Requests.forall(id =>
    entry(id).phase.in(Set("failing", "exhausted")) implies
      (entry(id).attempts == MaxAttempts and entry(id).committedAt == 0))
  val DeduplicationRequiresMarker = Requests.forall(id =>
    (entry(id).phase == "deduplicated") implies s.marker)
  temporal MarkerPersists = always((s.marker implies next(s.marker)).orKeep(s))
  def terminal(id: int): bool = entry(id).phase.in(Set("done", "exhausted", "deduplicated"))
  temporal RequestsSettle = Requests.forall(id =>
    (entry(id).phase != "idle").leadsTo(terminal(id)))
  temporal FairRequestsSettle = Requests.forall(id => advance(id).weakFair(s))
    .implies(RequestsSettle)

  run refusedMarkerRetriesBeforeCompletionTest = init.then(submit(0))
    .then(beginAttempt(0)).then(settleScrub(0, true)).then(settleMarker(0, false))
    .expect(not(s.marker) and entry(0).phase == "queued")
    .then(beginAttempt(0)).then(settleScrub(0, true)).then(settleMarker(0, true))
    .then(settleNotice(0, true)).expect(s.marker and terminal(0) and entry(0).attempts == 2)
  run refusedMarkerCanExhaustWithoutCompletionTest = init.then(submit(0))
    .then(beginAttempt(0)).then(settleScrub(0, true)).then(settleMarker(0, false))
    .then(beginAttempt(0)).then(settleScrub(0, true)).then(settleMarker(0, false))
    .then(beginAttempt(0)).then(settleScrub(0, true)).then(settleMarker(0, false))
    .then(beginAttempt(0)).then(settleScrub(0, true)).then(settleMarker(0, false))
    .then(settleFailureNotice(0))
    .expect(not(s.marker) and entry(0).phase == "exhausted" and entry(0).notice == "none")
  run observerRejectionRetainsReceiptTest = init.then(submit(0)).then(beginAttempt(0))
    .then(settleScrub(0, true)).then(settleMarker(0, true)).then(settleNotice(0, false))
    .then(submit(1)).expect(s.marker and terminal(0) and entry(0).notice == "rejected"
      and entry(0).attempts == 1 and entry(1).phase == "deduplicated")
  run overlappingMissesMayBothCommitTest = init.then(submit(0)).then(submit(1))
    .then(beginAttempt(0)).then(beginAttempt(1)).then(settleScrub(0, true))
    .then(settleMarker(0, true)).then(settleScrub(1, true)).then(settleMarker(1, true))
    .then(settleNotice(0, false)).then(settleNotice(1, true))
    .expect(CompletionRequiresReceipt and terminal(0) and terminal(1))
}

// nodePinnedFetch turns a WHATWG URL host into node:http/https request
// options. The transport gets the bare name or address, the Host header keeps
// the URL form, and TLS offers a server name only for a DNS name.
module PinnedTransportHost {
  // hostKind: 0 the DNS name localhost, 1 the IPv4 literal 127.0.0.1,
  // 2 the IPv6 literal [::1] (WHATWG URL keeps the brackets).
  // scheme: 0 http, 1 https.
  // transportHost: 0 the bare name or address, 1 the bracketed URL form.
  // sni: 0 none, 1 the DNS name, 2 a bare IP address, 3 a bracketed one.
  // outcome: -1 not sent, 0 delivered, 2 certificate rejected.
  // The local certificate names localhost, 127.0.0.1 and ::1.
  var hostKind: int
  var scheme: int
  var phase: int
  var transportHost: int
  var sni: int
  var hostHeaderBracketed: bool
  var outcome: int

  pure def isIpLiteral(kind: int): bool = kind == 1 or kind == 2

  action init = {
    nondet chosenHost = Set(0, 1, 2).oneOf()
    nondet chosenScheme = Set(0, 1).oneOf()
    all {
      hostKind' = chosenHost, scheme' = chosenScheme, phase' = 0,
      transportHost' = 0, sni' = 0, hostHeaderBracketed' = false,
      outcome' = -1
    }
  }
  // nodePinnedFetch: strip the IPv6 brackets for the transport and set
  // servername only for an https DNS name.
  action build = all {
    phase == 0, phase' = 1, hostKind' = hostKind, scheme' = scheme,
    transportHost' = 0,
    sni' = if (scheme == 1 and not(isIpLiteral(hostKind))) 1 else 0,
    // node:http writes the Host header from the host it was given and
    // brackets an IPv6 address.
    hostHeaderBracketed' = hostKind == 2,
    outcome' = outcome
  }
  // node:https checks the certificate against servername when it is set,
  // else against the host. A bracketed address is neither a certificate IP
  // nor a certificate DNS name. The guard's pinned lookup connects either
  // form to the screened address.
  action connect = all {
    phase == 1, phase' = 2, hostKind' = hostKind, scheme' = scheme,
    transportHost' = transportHost, sni' = sni,
    hostHeaderBracketed' = hostHeaderBracketed,
    outcome' =
      if (scheme == 1 and (sni == 3 or (sni == 0 and transportHost == 1))) 2
      else 0
  }
  action stay = all {
    phase == 2, phase' = phase, hostKind' = hostKind, scheme' = scheme,
    transportHost' = transportHost, sni' = sni,
    hostHeaderBracketed' = hostHeaderBracketed, outcome' = outcome
  }
  action step = any { build, connect, stay }

  val Delivered = phase != 2 or outcome == 0
  val TransportGetsBareHost = phase == 0 or transportHost == 0
  val NoIpServerName = sni != 2 and sni != 3
  val DnsNameServerName =
    phase == 0 or scheme == 0 or isIpLiteral(hostKind) or sni == 1
  val HostHeaderKeepsUrlForm =
    phase == 0 or hostHeaderBracketed == (hostKind == 2)
}

